update.getPayload:
const v = context.panel.formValue();
// One item per line in the box, comma-separated on the way out.
const list = (s) => (s || '').split('\n').map((x) => x.trim()).filter((x) => x.length).join(',');
return {
  client: v.client,
  host: v.host,
  name: v.name,
  cron: v.cron,
  machine: v.machine ? 'true' : 'false',
  paths: list(v.paths),
  volumes: list(v.volumes),
  databases: list(v.databases),
  keep_daily: Number(v.keep_daily) || 0,
  keep_weekly: Number(v.keep_weekly) || 0,
  keep_monthly: Number(v.keep_monthly) || 0,
};

update.code:
if (context.panel.response && context.panel.response.state === 'Done') {
  context.grafana.notifySuccess(['Backups', 'Schedule saved']);
  context.grafana.refresh();
} else {
  context.grafana.notifyError(['Backups', 'The API refused that: ' + JSON.stringify(context.panel.response)]);
}

